/**
 * Indexer Factory Functions Module.
 *
 * @remarks
 * This module provides factory functions for creating indexer service fetchers.
 * Each factory takes configuration arguments and optional dependencies,
 * returning a specialized fetcher function.
 *
 * The Umbra indexer is an **untrusted** off-chain service that tracks on-chain events
 * and makes UTXO data and Merkle proofs queryable without scanning the entire chain.
 * Because the indexer is untrusted, callers are responsible for cryptographically
 * verifying all returned data against the on-chain Merkle tree before use.
 *
 * **API Endpoints (via ReadServiceClient):**
 * - `GET /v1/trees/:tree_index/proof/:insertion_index` - Merkle proof for a specific leaf
 * - `GET /v1/utxos?start=&end=&limit=` - UTXO data with pagination
 *
 * **Hash Encoding:**
 * All byte fields (hashes, keys, addresses) are base64-encoded in the read service protobuf response.
 *
 * **Dependency Injection:**
 * All factories support injecting a custom `fetch` implementation for testing
 * or environments without global fetch.
 *
 * **Trust Model:**
 * The indexer is UNTRUSTED. Callers must verify:
 * - UTXO commitments against the on-chain Indexed Merkle Tree.
 * - Merkle proof paths against the on-chain Merkle root.
 * - AES-encrypted data by decrypting with the recipient's private key and
 *   checking that the decrypted plaintext re-hashes to the stored commitment.
 *
 * @packageDocumentation
 */

import type {
  U32,
  U64,
  U128,
  U256LeBytes,
  X25519PublicKey,
  AesCiphertextWithMetadata,
  U128LeBytes,
  Year,
  Month,
  Day,
  Hour,
  Minute,
  Second,
} from "../types";
import { assertU256LeBytes, assertU128LeBytes } from "../types";
import type {
  MerkleProofFetcherFunction,
  MerkleProofData,
  GetMerkleProofFetcherArgs,
  GetMerkleProofFetcherDeps,
  BatchMerkleProofFetcherFunction,
  BatchMerkleProofResult,
  UtxoDataFetcherFunction,
  UtxoFetchResult,
  UtxoDataItem,
  GetUtxoDataFetcherArgs,
  GetUtxoDataFetcherDeps,
  H1Components,
  TimestampComponents,
} from "./interfaces";
import { decodeU128LeBytesToU128 } from "../common/converters/mathematics";
import { ReadServiceClient } from "@umbra-privacy/indexer-read-service-client";

// ============================================================================
// Constants
// ============================================================================

/**
 * Default pagination limit for UTXO queries.
 *
 * @remarks
 * This value is used when no explicit `limit` parameter is provided to the
 * UTXO fetcher function. It balances network payload size against the number
 * of round-trips required to scan a full tree.
 *
 * @internal
 */
const DEFAULT_UTXO_LIMIT = 1000n as U32;

/**
 * Maximum pagination limit for UTXO queries.
 *
 * @remarks
 * The indexer API enforces a server-side cap of 5000 items per response.
 * Requests above this value will be rejected with a validation error before
 * reaching the network.
 *
 * @internal
 */
const MAX_UTXO_LIMIT = 5000n as U32;

// ============================================================================
// Error Class
// ============================================================================

/**
 * Error class for indexer-related failures.
 *
 * @remarks
 * This error is thrown when indexer API calls fail due to network issues,
 * invalid responses, or server errors. It extends the standard `Error` class
 * with two additional structured fields:
 *
 * - `operation` — a machine-readable label for the failing operation, useful
 *   for programmatic error handling and logging.
 * - `statusCode` — the HTTP status code returned by the indexer, when
 *   applicable. This is `undefined` for network-level failures (e.g. DNS
 *   resolution failure, timeout).
 *
 * @example
 * ```typescript
 * try {
 *   const proofs = await fetchProof(0, [42]);
 * } catch (err) {
 *   if (err instanceof IndexerError) {
 *     console.error(`Operation: ${err.operation}, HTTP status: ${err.statusCode}`);
 *   }
 * }
 * ```
 *
 * @public
 */
export class IndexerError extends Error {
  /**
   * The indexer operation that failed.
   *
   * @remarks
   * This is a short camelCase label identifying which high-level operation
   * triggered the error (e.g. `"fetchMerkleProof"`, `"fetchUtxoData"`,
   * `"base64Conversion"`).
   *
   * @readonly
   */
  public readonly operation: string;

  /**
   * HTTP status code if available.
   *
   * @remarks
   * Present when the server responded with an HTTP error (4xx or 5xx).
   * `undefined` for transport-level failures such as network timeouts or
   * DNS resolution failures.
   *
   * @readonly
   */
  public readonly statusCode: number | undefined;

  /**
   * Creates a new IndexerError.
   *
   * @param operation - The operation that failed (e.g. `"fetchMerkleProof"`)
   * @param message - Descriptive error message for display to users or logs
   * @param statusCode - Optional HTTP status code (undefined for network failures)
   * @param cause - Optional underlying error that triggered this one
   */
  constructor(operation: string, message: string, statusCode?: number, cause?: Error) {
    super(`Indexer operation '${operation}' failed: ${message}`);
    this.name = "IndexerError";
    this.operation = operation;
    this.statusCode = statusCode;
    this.cause = cause;

     
    if (Error.captureStackTrace !== undefined) {
      Error.captureStackTrace(this, IndexerError);
    }
  }
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Decodes a base64 string to a raw byte array.
 *
 * @remarks
 * Uses the Node.js `Buffer` API when available (server-side / Node environments)
 * and falls back to the browser `atob` function in web environments. Both paths
 * produce an identical `Uint8Array` result.
 *
 * All byte fields returned by the indexer read service (hashes, keys, ciphertext)
 * are base64-encoded protobuf fields and must be decoded before use.
 *
 * @param base64 - The base64-encoded string to decode
 * @returns A `Uint8Array` containing the decoded raw bytes
 *
 * @internal
 */
function base64ToBytes(base64: string): Uint8Array {
  if (typeof Buffer !== "undefined") {
    return Buffer.from(base64, "base64");
  }
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let index = 0; index < binaryString.length; index++) {
    bytes[index] = binaryString.codePointAt(index) ?? 0;
  }
  return bytes;
}

/**
 * Converts a base64-encoded 32-byte value to a `U256LeBytes` branded type.
 *
 * @remarks
 * The indexer encodes all 256-bit field elements (Merkle roots, leaf hashes,
 * Merkle path nodes) as 32-byte little-endian byte arrays transmitted as base64.
 * This helper decodes and asserts the correct length before applying the brand.
 *
 * @param base64 - A base64-encoded string representing exactly 32 bytes
 * @returns A `U256LeBytes` (Uint8Array of length 32, little-endian)
 *
 * @throws {IndexerError} If the decoded byte array is not exactly 32 bytes
 *
 * @internal
 */
function base64ToU256LeBytes(base64: string): U256LeBytes {
  const bytes = base64ToBytes(base64);
  if (bytes.length !== 32) {
    throw new IndexerError(
      "base64Conversion",
      `Invalid byte length: expected 32 bytes, got ${String(bytes.length)}`,
    );
  }
  assertU256LeBytes(bytes);
  return bytes;
}

/**
 * Converts a base64-encoded 32-byte value to an `X25519PublicKey` branded type.
 *
 * @remarks
 * X25519 public keys are 32-byte Curve25519 field elements. The indexer stores
 * the depositor's ephemeral X25519 public key alongside each UTXO so that the
 * recipient can perform ECDH to derive the symmetric key for AES decryption.
 *
 * @param base64 - A base64-encoded string representing exactly 32 bytes
 * @returns An `X25519PublicKey` (Uint8Array of length 32)
 *
 * @throws {IndexerError} If the decoded byte array is not exactly 32 bytes
 *
 * @internal
 */
function base64ToX25519PublicKey(base64: string): X25519PublicKey {
  const bytes = base64ToBytes(base64);
  if (bytes.length !== 32) {
    throw new IndexerError(
      "base64Conversion",
      `Invalid X25519 public key length: expected 32 bytes, got ${String(bytes.length)}`,
    );
  }
  return bytes as X25519PublicKey;
}

/**
 * Decodes a base64-encoded AES ciphertext to `AesCiphertextWithMetadata`.
 *
 * @remarks
 * Each UTXO stores AES-256-GCM ciphertext that encodes the plaintext UTXO data
 * (amount, mint, sender, purpose). Only the intended recipient — who holds the
 * private X25519 key — can derive the symmetric AES key via ECDH and decrypt it.
 *
 * The ciphertext length is variable and includes authentication tag and nonce
 * metadata embedded in the wire format.
 *
 * @param base64 - A base64-encoded string representing the full ciphertext blob
 * @returns An `AesCiphertextWithMetadata` byte array
 *
 * @internal
 */
function base64ToAesCiphertext(base64: string): AesCiphertextWithMetadata {
  return base64ToBytes(base64) as AesCiphertextWithMetadata;
}

/**
 * Splits a base64-encoded 32-byte address into low and high `U128` parts.
 *
 * @remarks
 * Solana addresses (32 bytes) are too large for native circuit field elements
 * in the Arcium MPC. To fit, they are split into two 128-bit halves in
 * little-endian order:
 *
 * - `low`: bytes 0–15 interpreted as a little-endian U128
 * - `high`: bytes 16–31 interpreted as a little-endian U128
 *
 * This split is applied to the sender's wallet address and the token mint
 * address stored in the UTXO's `H1` header block.
 *
 * @param base64 - A base64-encoded string representing exactly 32 bytes
 * @returns An object with `low` and `high` U128 values
 *
 * @throws {IndexerError} If the decoded byte array is not exactly 32 bytes
 *
 * @internal
 */
function splitAddressBase64(base64: string): { low: U128; high: U128 } {
  const bytes = base64ToBytes(base64);
  if (bytes.length !== 32) {
    throw new IndexerError(
      "addressSplit",
      `Invalid address length: expected 32 bytes, got ${String(bytes.length)}`,
    );
  }

  const lowBytes = bytes.slice(0, 16);
  const highBytes = bytes.slice(16, 32);

  assertU128LeBytes(lowBytes);
  assertU128LeBytes(highBytes);

  return {
    low: decodeU128LeBytesToU128(lowBytes as U128LeBytes),
    high: decodeU128LeBytesToU128(highBytes as U128LeBytes),
  };
}

// ============================================================================
// Merkle Proof Fetcher Factory
// ============================================================================

/**
 * Creates a Merkle proof fetcher function.
 *
 * @remarks
 * This factory creates a function that fetches Merkle proofs from the indexer
 * read service via `GET /v1/trees/:tree_index/proof/:insertion_index`.
 *
 * **Purpose:**
 * Merkle proofs are required as inputs to Groth16 claim transactions. The proof
 * demonstrates that a UTXO commitment exists at a specific leaf position in the
 * on-chain Indexed Merkle Tree without revealing which UTXO is being claimed
 * (the ZK circuit hides this relationship).
 *
 * **Concurrency:**
 * When multiple `insertionIndices` are provided, all proof requests are issued
 * concurrently via `Promise.all`. The API supports only one leaf per request,
 * so N insertion indices result in N HTTP calls fired in parallel.
 *
 * **Caller Verification Requirement:**
 * Because the indexer is untrusted, callers must verify the returned `merkleRoot`
 * against the current on-chain root before submitting the Merkle path to the
 * ZK circuit. An incorrect proof will cause on-chain verification to fail.
 *
 * **API Endpoint:**
 * `GET /v1/trees/:tree_index/proof/:insertion_index`
 *
 * @param args - Required configuration
 * @param args.apiEndpoint - The base URL of the indexer read service
 * @param deps - Optional dependencies (inject a custom `fetch` for tests or non-browser envs)
 * @param deps.fetch - Custom fetch implementation; defaults to `globalThis.fetch`
 * @returns A {@link MerkleProofFetcherFunction} that, when called, fetches proofs
 *   for the specified leaves and returns them keyed by insertion index
 *
 * @throws {IndexerError} If `treeIndex` or any `insertionIndex` is not a non-negative integer
 * @throws {IndexerError} If the HTTP request to the indexer fails
 *
 * @example
 * ```typescript
 * const fetchProof = getMerkleProofFetcher({
 *   apiEndpoint: 'https://indexer.umbra.finance'
 * });
 *
 * // Fetch proofs for two leaves in tree 0
 * const proofs = await fetchProof(0, [42, 43]);
 * const proof = proofs.get(42);
 * if (proof !== undefined) {
 *   console.log('Merkle root:', proof.merkleRoot);
 *   console.log('Path length:', proof.merklePath.length);
 * }
 * ```
 *
 * @example
 * ```typescript
 * // Inject a custom fetch for unit testing
 * const fetchProof = getMerkleProofFetcher(
 *   { apiEndpoint: 'https://indexer.umbra.finance' },
 *   { fetch: mockFetch }
 * );
 * ```
 *
 * @see {@link MerkleProofFetcherFunction}
 * @see {@link MerkleProofData}
 * @public
 */
export function getMerkleProofFetcher(
  args: GetMerkleProofFetcherArgs,
  deps?: GetMerkleProofFetcherDeps,
): MerkleProofFetcherFunction {
  const { apiEndpoint } = args;
  const client = new ReadServiceClient({ endpoint: apiEndpoint, fetch: deps?.fetch });

  /**
   * Fetches Merkle proofs for one or more leaf positions in a given tree.
   *
   * @param treeIndex - The zero-based index of the Indexed Merkle Tree to query
   * @param insertionIndices - The zero-based leaf positions for which to fetch proofs.
   *   An empty array returns an empty Map immediately without any network calls.
   * @returns A `Map<insertionIndex, MerkleProofData>` containing one entry per requested leaf.
   *   The map preserves the 1-to-1 correspondence: if a leaf is requested, it appears in the result.
   *
   * @throws {IndexerError} If `treeIndex` is negative or non-integer
   * @throws {IndexerError} If any element of `insertionIndices` is negative or non-integer
   * @throws {IndexerError} If the HTTP request for any leaf fails
   */
  return async function fetchMerkleProof(
    treeIndex: U32,
    insertionIndices: readonly U32[],
  ): Promise<Map<U32, MerkleProofData>> {
    if (insertionIndices.length === 0) {
      return new Map();
    }

    if (treeIndex < 0n) {
      throw new IndexerError(
        "fetchMerkleProof",
        `Invalid tree index: ${String(treeIndex)}. Must be non-negative.`,
      );
    }

    const results = new Map<U32, MerkleProofData>();

    // Fetch proofs for each leaf (API supports single leaf per request)
    const fetchPromises = insertionIndices.map(async (insertionIndex) => {
      if (insertionIndex < 0n) {
        throw new IndexerError(
          "fetchMerkleProof",
          `Invalid insertion index: ${String(insertionIndex)}. Must be non-negative.`,
        );
      }

      let data;
      try {
        data = await client.getProof(treeIndex, insertionIndex);
      } catch (error) {
        throw new IndexerError(
          "fetchMerkleProof",
          `Failed to fetch proof for leaf ${String(insertionIndex)}: ${error instanceof Error ? error.message : String(error)}`,
          undefined,
          error instanceof Error ? error : undefined,
        );
      }

      const merkleRoot = base64ToU256LeBytes(data.root);
      const merklePath = data.proof.map((hash) => base64ToU256LeBytes(hash));
      const leaf = base64ToU256LeBytes(data.leaf);

      return {
        insertionIndex,
        data: {
          merkleRoot,
          treeIndex: data.tree_index as U32,
          insertionIndex: data.insertion_index as U32,
          merklePath,
          leaf,
        },
      };
    });

    const proofResults = await Promise.all(fetchPromises);

    for (const { insertionIndex, data } of proofResults) {
      results.set(insertionIndex, data);
    }

    return results;
  };
}

// ============================================================================
// Batch Merkle Proof Fetcher Factory
// ============================================================================

/**
 * Creates a batch Merkle proof fetcher function.
 *
 * @remarks
 * Unlike {@link getMerkleProofFetcher} which fires individual HTTP requests per leaf,
 * this fetcher uses the `POST /v1/trees/:tree_index/proofs` batch endpoint.
 * The indexer generates all proofs under a single tree read lock, guaranteeing
 * a consistent Merkle root across all entries. This is essential for ZK batch
 * claims where the circuit requires a single root for all proved leaves.
 *
 * @param args - Factory arguments (apiEndpoint).
 * @param deps - Optional dependency overrides (custom fetch).
 * @returns A {@link BatchMerkleProofFetcherFunction}.
 *
 * @public
 */
export function getBatchMerkleProofFetcher(
  args: GetMerkleProofFetcherArgs,
  deps?: GetMerkleProofFetcherDeps,
): BatchMerkleProofFetcherFunction {
  const { apiEndpoint } = args;
  const client = new ReadServiceClient({ endpoint: apiEndpoint, fetch: deps?.fetch });

  return async function fetchBatchMerkleProof(
    treeIndex: U32,
    insertionIndices: readonly U32[],
  ): Promise<BatchMerkleProofResult> {
    if (insertionIndices.length === 0) {
      return { root: new Uint8Array(32) as U256LeBytes, proofs: new Map() };
    }

    if (treeIndex < 0n) {
      throw new IndexerError(
        "fetchBatchMerkleProof",
        `Invalid tree index: ${String(treeIndex)}. Must be non-negative.`,
      );
    }

    for (const idx of insertionIndices) {
      if (idx < 0n) {
        throw new IndexerError(
          "fetchBatchMerkleProof",
          `Invalid insertion index: ${String(idx)}. Must be non-negative.`,
        );
      }
    }

    let data;
    try {
      data = await client.getBatchProof(
        treeIndex,
        insertionIndices.map((idx) => BigInt(idx)),
      );
    } catch (error) {
      throw new IndexerError(
        "fetchBatchMerkleProof",
        `Failed to fetch batch proofs: ${error instanceof Error ? error.message : String(error)}`,
        undefined,
        error instanceof Error ? error : undefined,
      );
    }

    const root = base64ToU256LeBytes(data.root);

    const proofs = new Map<
      U32,
      { merklePath: U256LeBytes[]; leaf: U256LeBytes }
    >();
    for (const entry of data.proofs) {
      proofs.set(entry.insertion_index as U32, {
        merklePath: entry.proof.map((hash: string) => base64ToU256LeBytes(hash)),
        leaf: base64ToU256LeBytes(entry.leaf),
      });
    }

    return { root, proofs };
  };
}

// ============================================================================
// UTXO Data Fetcher Factory
// ============================================================================

/**
 * Creates a UTXO data fetcher function.
 *
 * @remarks
 * This factory creates a function that fetches UTXO data from the indexer
 * read service via `GET /v1/utxos?start=&end=&limit=` with pagination support.
 *
 * **Purpose:**
 * Recipients use this function to scan for UTXOs sent to them. Because UTXOs
 * are encrypted, the recipient must attempt to decrypt each UTXO's AES ciphertext
 * with their private key to determine which UTXOs belong to them.
 *
 * **Absolute Index Calculation:**
 * The API uses a global "absolute index" that spans all trees. The formula is:
 * ```
 * absoluteIndex = treeIndex * 1,048,576 + insertionIndex
 * ```
 * where 1,048,576 = 2^20 is the capacity of each Indexed Merkle Tree.
 *
 * **Pagination:**
 * The API returns up to `limit` items per response. To scan a range larger than
 * one page, iterate using the cursor pattern:
 * - Use `startIndex` and optional `endIndex` to define the absolute index range
 * - Use `limit` to control page size (default: {@link DEFAULT_UTXO_LIMIT}, max: {@link MAX_UTXO_LIMIT})
 * - Use `nextCursor` from the result as `startIndex` for the next page
 * - Stop when `hasMore` is `false`
 *
 * **Caller Verification Requirement:**
 * Because the indexer is untrusted, callers must verify each UTXO's
 * `finalCommitment` against the on-chain Merkle tree after decryption.
 *
 * **API Endpoint:**
 * `GET /v1/utxos?start=&end=&limit=`
 *
 * @param args - Required configuration
 * @param args.apiEndpoint - The base URL of the indexer read service
 * @param deps - Optional dependencies (inject a custom `fetch` for tests or non-browser envs)
 * @param deps.fetch - Custom fetch implementation; defaults to `globalThis.fetch`
 * @returns A {@link UtxoDataFetcherFunction} that fetches one page of UTXO data
 *
 * @throws {IndexerError} If `startIndex` is negative
 * @throws {IndexerError} If `endIndex` is defined and less than `startIndex`
 * @throws {IndexerError} If `limit` is outside the range [1, {@link MAX_UTXO_LIMIT}]
 * @throws {IndexerError} If the HTTP request fails
 * @throws {IndexerError} If any item in the response cannot be parsed
 *
 * @example
 * ```typescript
 * const fetchUtxoData = getUtxoDataFetcher({
 *   apiEndpoint: 'https://indexer.umbra.finance'
 * });
 *
 * // Scan all UTXOs from the beginning
 * let result = await fetchUtxoData(0n, undefined, 1000);
 * console.log(`Found ${result.items.size} UTXOs, hasMore=${result.hasMore}`);
 *
 * // Continue pagination
 * while (result.hasMore && result.nextCursor !== undefined) {
 *   result = await fetchUtxoData(result.nextCursor, undefined, 1000);
 * }
 * ```
 *
 * @example
 * ```typescript
 * // Fetch only UTXOs within tree 0 (absoluteIndex 0 to 1048575)
 * const result = await fetchUtxoData(0n, 1048575n, 5000);
 * ```
 *
 * @see {@link UtxoDataFetcherFunction}
 * @see {@link UtxoFetchResult}
 * @see {@link UtxoDataItem}
 * @public
 */
export function getUtxoDataFetcher(
  args: GetUtxoDataFetcherArgs,
  deps?: GetUtxoDataFetcherDeps,
): UtxoDataFetcherFunction {
  const { apiEndpoint } = args;
  const client = new ReadServiceClient({ endpoint: apiEndpoint, fetch: deps?.fetch });

  /**
   * Fetches one page of UTXO data from the indexer.
   *
   * @param startIndex - The inclusive lower bound of the absolute index range to query.
   *   Must be a non-negative bigint. Use `0n` to start from the first ever UTXO.
   * @param endIndex - Optional inclusive upper bound of the absolute index range.
   *   If omitted, the server returns all UTXOs from `startIndex` up to `limit`.
   * @param limit - The maximum number of items to return in this page.
   *   @defaultValue {@link DEFAULT_UTXO_LIMIT} (1000)
   *   Must be in the range [1, {@link MAX_UTXO_LIMIT}] (5000).
   * @returns A {@link UtxoFetchResult} with the parsed UTXO items, pagination cursor,
   *   and `hasMore` flag.
   *
   * @throws {IndexerError} If `startIndex` is negative
   * @throws {IndexerError} If `endIndex` is defined and less than `startIndex`
   * @throws {IndexerError} If `limit` is out of range
   * @throws {IndexerError} If the HTTP request fails or any item cannot be parsed
   */
  return async function fetchUtxoData(
    startIndex: bigint,
    endIndex?: bigint,
    limit?: U32,
  ): Promise<UtxoFetchResult> {
    if (startIndex < 0n) {
      throw new IndexerError(
        "fetchUtxoData",
        `Invalid start index: ${String(startIndex)}. Must be non-negative.`,
      );
    }

    if (endIndex !== undefined && endIndex < startIndex) {
      throw new IndexerError(
        "fetchUtxoData",
        `Invalid end index: ${String(endIndex)}. Must be >= start index (${String(startIndex)}).`,
      );
    }

    const effectiveLimit = limit ?? DEFAULT_UTXO_LIMIT;
    if (effectiveLimit < 1n || effectiveLimit > MAX_UTXO_LIMIT) {
      throw new IndexerError(
        "fetchUtxoData",
        `Invalid limit: ${String(effectiveLimit)}. Must be between 1 and ${String(MAX_UTXO_LIMIT)}.`,
      );
    }

    let response;
    try {
      response = await client.getUtxoData({
        start: startIndex,
        end: endIndex,
        limit: effectiveLimit,
      });
    } catch (error) {
      throw new IndexerError(
        "fetchUtxoData",
        `Network error: ${error instanceof Error ? error.message : String(error)}`,
        undefined,
        error instanceof Error ? error : undefined,
      );
    }

    const items = new Map<U32, UtxoDataItem>();

    for (const item of response.items) {
      try {
        const senderAddress = splitAddressBase64(item.h1_sender_address);
        const mintAddress = splitAddressBase64(item.h1_mint_address);

        const timestamp: TimestampComponents = {
          year: item.h1_year as Year,
          month: item.h1_month as Month,
          day: item.h1_day as Day,
          hour: item.h1_hour as Hour,
          minute: item.h1_minute as Minute,
          second: item.h1_second as Second,
        };

        const h1Components: H1Components = {
          version: BigInt(item.h1_version) as U64,
          commitmentIndex: BigInt(item.h1_commitment_index) as U128,
          senderAddressLow: senderAddress.low,
          senderAddressHigh: senderAddress.high,
          relayerFixedSolFees: item.h1_relayer_fixed_sol_fees as U64,
          mintAddressLow: mintAddress.low,
          mintAddressHigh: mintAddress.high,
          timestamp,
          poolVolumeSpl: item.h1_pool_volume_spl as U64,
          poolVolumeSol: item.h1_pool_volume_sol as U64,
        };

        const utxoItem: UtxoDataItem = {
          absoluteIndex: item.absolute_index,
          treeIndex: item.tree_index as U32,
          insertionIndex: item.insertion_index as U32,
          finalCommitment: base64ToU256LeBytes(item.final_commitment),
          h1Components,
          h1Hash: base64ToU256LeBytes(item.h1_hash),
          h2Hash: base64ToU256LeBytes(item.h2_hash),
          aesEncryptedData: base64ToAesCiphertext(item.aes_encrypted_data),
          depositorX25519PublicKey: base64ToX25519PublicKey(item.depositor_x25519_public_key),
          timestamp: item.timestamp as U64,
          slot: item.slot as U64,
          eventType: item.event_type as "deposit" | "callback",
        };

        items.set(item.insertion_index as U32, utxoItem);
      } catch (error) {
        throw new IndexerError(
          "fetchUtxoData",
          `Failed to parse UTXO data for index ${String(item.absolute_index)}: ${error instanceof Error ? error.message : String(error)}`,
          undefined,
          error instanceof Error ? error : undefined,
        );
      }
    }

    return {
      items,
      hasMore: response.has_more,
      nextCursor: response.next_cursor ?? undefined,
      totalCount: response.total_count as U64,
    };
  };
}
